cards=[]
for i,line in enumerate(MAJOR.splitlines()):
    en,th,up,rev,love,advice,scene=line.split('|')
    cards.append(dict(id=f'major-{i:02}',order=i,arcana='major',suit=None,rank=i,name_en=en,name_th=th,display_mark=ROMAN[i],upright_th=up,reversed_th=rev,love_th=love,advice_th=advice,scene_prompt=scene,source_id='waite-symbolism',interpretation_origin='modern_editorial_adaptation',visual_adaptation='ภาพใหม่เชิงสัญลักษณ์บนฐาน RWS ไม่ใช่การทำสำเนาภาพเดิม'))
for suit,raw in MINOR.items():
    for i,line in enumerate(raw.splitlines()):
        rank,up,rev,love,advice,scene=line.split('|')
        marker=ROMAN[i+1] if i<10 else COURT[rank]
        cards.append(dict(id=f'{suit}-{rank}',order=len(cards),arcana='minor',suit=suit,rank=rank,name_en=f'{rank.title()} of {suit.title()}',name_th=f'{THR[i]}{SUITS[suit][0]}',display_mark=marker,upright_th=up,reversed_th=rev,love_th=love,advice_th=advice,scene_prompt=scene,source_id='waite-symbolism',interpretation_origin='modern_editorial_adaptation',visual_adaptation='ภาพใหม่รักษาแกนสัญลักษณ์และหมวด; รายละเอียดภาพเป็นการออกแบบของสำรับ'))
for c in cards:
    c['keywords_th']=c['upright_th'].split(' ')
    c['work_th']=f"พิจารณาเรื่องงานและทรัพยากรผ่านแกน ‘{c['upright_th']}’ แล้วเลือกการกระทำ: {c['advice_th']}"
    c['reflection_th']=f"ในสถานการณ์นี้ ฉันจะ{c['advice_th']}ได้อย่างไร?"
    c['image']=f"assets/cards/{c['id']}.png"
    c['image_web']=f"assets/web/{c['id']}.webp"
    c['alt_th']=f"ไพ่ {c['name_th']} ({c['name_en']}) ลายเส้นภาพพิมพ์กอทิก หมึกดำบนกระดาษงาช้างแต้มแดงหม่น"
    identifier=f"Top identifier exactly {c['display_mark']}." if c['arcana']=='major' or c['rank'] in RANKS[:10] else f"Top identifier is {c['display_mark']} ONLY, no numeral, no letters."
    suitnote='' if not c['suit'] else f" Small bottom center suit emblem: {dict(wands='a sprouting wooden staff',cups='one chalice',swords='one upright sword',pentacles='one five-pointed star enclosed in circle')[c['suit']]}. Bottom emblem is separate from scene object count."
    c['generation_prompt']=STYLE+identifier+suitnote+' CENTRAL SCENE: '+c['scene_prompt']
(ROOT/'data/cards.json').write_text(json.dumps({'schema_version':'1.0.0','deck_id':'gothic-ivory-rose','title_th':'สำรับกอทิกงาช้างและกุหลาบ','system':'RWS-inspired','language':'th','meaning_policy':'เรียบเรียงสมัยใหม่เพื่อสะท้อนสถานการณ์ ไม่ใช่คำแปลตรงจาก Waite และไม่รับรองการทำนายอนาคต','cards':cards},ensure_ascii=False,indent=2))
(ROOT/'data/generation_jobs.json').write_text(json.dumps([{'id':c['id'],'prompt':c['generation_prompt']} for c in cards if c['id'] not in ['major-13','major-18']],ensure_ascii=False,indent=2))
(ROOT/'data/suits.json').write_text(json.dumps({k:dict(name_th=v[0],element=v[1],theme_th=v[2]) for k,v in SUITS.items()},ensure_ascii=False,indent=2))
assert len(cards)==78 and len({c['id'] for c in cards})==78
